result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/licexpr.py", "content": """"SPDX-style license expression evaluator.

Grammar:
    expr   := term ( SP "OR" SP term )*
    term   := factor ( SP "AND" SP factor )*
    factor := LICENSE | "(" SP expr SP ")"

AND binds tighter than OR. Licenses are limited to:
    MIT, Apache-2.0, GPL-3.0, AGPL-3.0, BSL-1.1

AST node shapes:
    ("lic", name)
    ("and", left, right)
    ("or",  left, right)
"""

import json

LICENSES = {"MIT", "Apache-2.0", "GPL-3.0", "AGPL-3.0", "BSL-1.1"}


class LicenseParseError(ValueError):
    def __init__(self, message, pos):
        super().__init__(f"{message} at position {pos}")
        self.pos = pos
        self.message = message


def _tokenize(s):
    """Return list of (kind, value, pos) tokens. kinds: ident, lparen, rparen."""
    tokens = []
    i, n = 0, len(s)
    while i < n:
        c = s[i]
        if c.isspace():
            i += 1
        elif c == "(":
            tokens.append(("lparen", "(", i))
            i += 1
        elif c == ")":
            tokens.append(("rparen", ")", i))
            i += 1
        else:
            j = i
            while j < n and not s[j].isspace() and s[j] not in "()":
                j += 1
            word = s[i:j]
            if word not in LICENSES and word not in ("AND", "OR"):
                raise LicenseParseError(f"unknown token {word!r}", i)
            if word in LICENSES:
                # A bare operator keyword is never valid as a license name;
                # conversely a known license can't be an operator.
                tokens.append(("ident", word, i))
            else:
                tokens.append(("op", word, i))
            i = j
    return tokens


class _Parser:
    def __init__(self, s):
        self.tokens = _tokenize(s)
        self.i = 0

    def peek(self):
        return self.tokens[self.i] if self.i < len(self.tokens) else None

    def next(self):
        tok = self.peek()
        if tok is None:
            raise LicenseParseError("unexpected end of expression", len(str(self)))
        self.i += 1
        return tok

    def parse_expr(self):
        node = self.parse_term()
        while (tok := self.peek()) and tok[0] == "op" and tok[1] == "OR":
            self.next()
            node = ("or", node, self.parse_term())
        return node

    def parse_term(self):
        node = self.parse_factor()
        while (tok := self.peek()) and tok[0] == "op" and tok[1] == "AND":
            self.next()
            node = ("and", node, self.parse_factor())
        return node

    def parse_factor(self):
        tok = self.peek()
        if tok is None:
            raise LicenseParseError("unexpected end of expression",
                                    sum(len(t[1]) + 1 for t in self.tokens))
        kind, value, pos = tok
        if kind == "lparen":
            self.next()
            node = self.parse_expr()
            close = self.peek()
            if close is None or close[0] != "rparen":
                raise LicenseParseError("expected ')'", close[2] if close else pos)
            self.next()
            return node
        if kind == "ident":
            self.next()
            return ("lic", value)
        if kind == "op" and value == "AND":
            raise LicenseParseError("'AND' without preceding term", pos)
        raise LicenseParseError(f"expected license or '(' , got {value!r}", pos)


def parse(s):
    """Parse a license expression string into an AST."""
    if not isinstance(s, str) or not s.strip():
        raise LicenseParseError("empty expression", 0)
    parser = _Parser(s)
    node = parser.parse_expr()
    leftover = parser.peek()
    if leftover is not None:
        raise LicenseParseError(
            f"unexpected trailing input {leftover[1]!r}", leftover[2])
    return node


def _collect(ast):
    """All license names appearing in the AST."""
    if ast[0] == "lic":
        return {ast[1]}
    return _collect(ast[1]) | _collect(ast[2])


def required(ast):
    """Licenses that must individually be accepted under any policy
    (i.e., licenses that appear in every branch). For reporting only;
    use satisfiable_under for decisions."""
    return _collect(ast)


def satisfiable_under(ast, policy):
    """True if the expression can be satisfied by accepting exactly the
    licenses in `policy` (a set).

    OR : satisfied if any branch is satisfied.
    AND: satisfied only if all branches are satisfied.
    lic: satisfied iff the license is in the policy.
    """
    kind = ast[0]
    if kind == "lic":
        return ast[1] in policy
    if kind == "and":
        return satisfiable_under(ast[1], policy) and satisfiable_under(ast[2], policy)
    if kind == "or":
        return satisfiable_under(ast[1], policy) or satisfiable_under(ast[2], policy)
    raise ValueError(f"bad AST node: {ast!r}")


def audit(deps, policy, path="deps.json"):
    """Given {package: expression} and an accepted-license set, return
    [(package, expression, acceptable_bool), ...]."""
    results = []
    for pkg, expr_text in deps.items():
        try:
            ast = parse(expr_text)
        except LicenseParseError as exc:
            raise LicenseParseError(f"{path}: package {pkg!r}: {exc.message}",
                                    exc.pos) from exc
        results.append((pkg, expr_text, satisfiable_under(ast, policy)))
    return results


if __name__ == "__main__":
    with open("deps.json") as fh:
        deps = json.load(fh)
    org_policy = {"MIT", "Apache-2.0"}
    print(f"Org policy accepts: {sorted(org_policy)}\n")
    for pkg, expr_text, ok in audit(deps, org_policy):
        verdict = "YES" if ok else "no "
        print(f"[{verdict}] {pkg:<8} {expr_text}")
